    'crossing' => 
    array (
      0 => 
      array (
        'en' => 'Rupaidiha is a small town in Bahraich district, Uttar Pradesh, on the India–Nepal border. It sits opposite Nepalgunj in Banke district, Nepal. The crossing point and immigration office on the Nepal side are at Jamunaha.',
        'ne' => 'रुपैडिहा भारतको उत्तर प्रदेशको बहराइच जिल्लामा पर्ने भारत–नेपाल सीमाको सानो सहर हो। यो नेपालको बाँके जिल्लाको नेपालगन्जको सामुन्ने छ। नेपालतर्फको नाका र अध्यागमन कार्यालय जमुनाहामा छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'en.wikipedia.org',
            'url' => 'https://en.wikipedia.org/wiki/Rupaidiha',
          ),
          1 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/lumbini-pradesh/2026/01/31/en/jamuna-border-crossing-opens-to-third-country-nationals-after-6-years-57-15.html',
          ),
        ),
      ),
      1 => 
      array (
        'en' => 'Nepalgunj city is about 5 km north of the border crossing.',
        'ne' => 'नेपालगन्ज सहर सीमा नाकाबाट करिब ५ किलोमिटर उत्तरमा छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'dlca.logcluster.org',
            'url' => 'https://dlca.logcluster.org/node/5180',
          ),
        ),
      ),
      2 => 
      array (
        'en' => 'Rupaidiha is an authorised land Immigration Check Post on the India–Nepal border, run by India\'s Bureau of Immigration. The Bureau\'s list as of 30 December 2025 shows it as one of only two land ports in India where e-Visa holders can enter; the other is Raxaul.',
        'ne' => 'रुपैडिहा भारत–नेपाल सीमामा रहेको अधिकृत स्थल अध्यागमन जाँच चौकी हो, जसलाई भारतको अध्यागमन ब्युरो (Bureau of Immigration) ले सञ्चालन गर्छ। ३० डिसेम्बर २०२५ सम्मको ब्युरोको सूचीअनुसार ई-भिसा भएका विदेशी प्रवेश गर्न पाउने भारतका दुई स्थल नाकामध्ये रुपैडिहा एक हो; अर्को रक्सौल हो।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'xn--i1b5bzbybhfo5c8b4bxh.xn--11b7cb3a6a.xn--h2brj9c',
            'url' => 'https://xn--i1b5bzbybhfo5c8b4bxh.xn--11b7cb3a6a.xn--h2brj9c/sites/default/files/2026-01/List_of_ICPs_%28Immigration_Checkpost%29_20012026.pdf',
          ),
        ),
      ),
      3 => 
      array (
        'en' => 'On the Nepal side, Jamunaha (Nepalgunj) is one of Nepal\'s immigration entry points. After about six years, the Jamunaha immigration office fully resumed arrival and departure services for foreign nationals in late January 2026. Third-country travellers can now cross here in both directions.',
        'ne' => 'नेपालतर्फ जमुनाहा (नेपालगन्ज) नेपालका अध्यागमन प्रवेश नाकामध्ये एक हो। करिब छ वर्षपछि जनवरी २०२६ को अन्त्यतिर जमुनाहा अध्यागमन कार्यालयले विदेशी नागरिकका लागि आगमन र प्रस्थान सेवा पूर्ण रूपमा फेरि सुरु गर्‍यो। अब तेस्रो देशका यात्रु यहाँबाट दुवैतर्फ आवतजावत गर्न सक्छन्।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/lumbini-pradesh/2026/01/31/en/jamuna-border-crossing-opens-to-third-country-nationals-after-6-years-57-15.html',
          ),
          1 => 
          array (
            'label' => 'diplomatnepal.com',
            'url' => 'https://diplomatnepal.com/news/jamunaha-border-reopens-for-third-country-tourists-after-six-years/',
          ),
        ),
      ),
      4 => 
      array (
        'en' => 'The Rupaidiha land port (about 115 acres) is Uttar Pradesh\'s first land port. The Prime Ministers of India and Nepal inaugurated it and its mirror Integrated Check Post (ICP) at Nepalgunj on 1 June 2023. The Nepalgunj ICP was built with Indian grant assistance and handed over to Nepal in April 2024. It is managed by Nepal\'s Intermodal Transport Development Board and has customs offices, quarantine, warehouses and bank counters, and handles cargo vehicle checks.',
        'ne' => 'रुपैडिहा स्थल बन्दरगाह (करिब ११५ एकड) उत्तर प्रदेशको पहिलो स्थल बन्दरगाह हो। भारत र नेपालका प्रधानमन्त्रीले यसको र नेपालगन्जको जोडी एकीकृत जाँच चौकी (ICP) को १ जुन २०२३ मा उद्घाटन गरेका थिए। नेपालगन्ज ICP भारतको अनुदान सहयोगमा बनेको हो र अप्रिल २०२४ मा नेपाललाई हस्तान्तरण गरिएको थियो। यसको व्यवस्थापन नेपाल इन्टरमोडल यातायात विकास समितिले गर्छ। यसमा भन्सार कार्यालय, क्वारेन्टाइन, गोदाम र बैंक काउन्टर छन्, र यहाँ मालवाहक सवारीको जाँच हुन्छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'www.tribuneindia.com',
            'url' => 'https://www.tribuneindia.com/news/nation/pm-modi-nepalese-counterpart-prachanda-to-inaugurate-ups-first-land-port-513258',
          ),
          1 => 
          array (
            'label' => 'www.indembkathmandu.gov.in',
            'url' => 'https://www.indembkathmandu.gov.in/media-detail/43',
          ),
          2 => 
          array (
            'label' => 'myrepublica.nagariknetwork.com',
            'url' => 'https://myrepublica.nagariknetwork.com/news/nepalgunj-icp-handed-over-to-nepal-to-come-into-operation-from-may-8',
          ),
        ),
      ),
      5 => 
      array (
        'en' => 'On the Indian side, the border is guarded by the Sashastra Seema Bal (SSB), which checks people entering at Rupaidiha.',
        'ne' => 'भारततर्फ सशस्त्र सीमा बल (SSB) ले सीमाको सुरक्षा गर्छ र रुपैडिहाबाट प्रवेश गर्नेहरूको जाँच गर्छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'www.etvbharat.com',
            'url' => 'https://www.etvbharat.com/en/state/two-foreign-nationals-jailed-for-illegal-entry-at-indo-nepal-border-in-uttar-pradesh-enn26040801766',
          ),
        ),
      ),
      6 => 
      array (
        'en' => 'The crossing can be fully closed for security reasons, such as elections. Before Nepal\'s general election on 5 March 2026, the District Administration Office in Banke closed all of Banke\'s border crossings with India for 72 hours. Jamunaha has also been closed during state assembly elections in Uttar Pradesh.',
        'ne' => 'निर्वाचनजस्ता सुरक्षा कारणले नाका पूर्ण रूपमा बन्द हुन सक्छ। नेपालको ५ मार्च २०२६ (फागुन २१, २०८२) को आम निर्वाचनअघि जिल्ला प्रशासन कार्यालय बाँकेले भारतसँग जोडिएका बाँकेका सबै नाका ७२ घण्टा बन्द गरेको थियो। उत्तर प्रदेशको विधानसभा निर्वाचनका बेला पनि जमुनाहा नाका बन्द भएको छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'english.ratopati.com',
            'url' => 'https://english.ratopati.com/story/50541/house-of-representatives-election-all-border-crossings-in-banke-to-be-closed-for-72-hours',
          ),
          1 => 
          array (
            'label' => 'en.wikipedia.org',
            'url' => 'https://en.wikipedia.org/wiki/2026_Nepalese_general_election',
          ),
          2 => 
          array (
            'label' => 'myrepublica.nagariknetwork.com',
            'url' => 'https://myrepublica.nagariknetwork.com/news/jamunaha-border-point-to-remain-closed-for-60-hrs',
          ),
        ),
      ),
      7 => 
      array (
        'en' => 'In October 2026, the District Administration Office in Banke set up a passenger help desk at Jamunaha, staffed by Nepal Police and Traffic Police, to protect people returning from India for Dashain and Tihar from robbery and fraud. Similar desks were to run at the Nepalgunj and Kohalpur bus parks.',
        'ne' => 'अक्टोबर २०२६ मा दसैँ–तिहारका लागि भारतबाट फर्कने यात्रुलाई लुटपाट र ठगीबाट जोगाउन जिल्ला प्रशासन कार्यालय बाँकेले जमुनाहामा नेपाल प्रहरी र ट्राफिक प्रहरी खटाएर यात्रु सहायता कक्ष (हेल्प डेस्क) राख्यो। नेपालगन्ज र कोहलपुरका बसपार्कमा पनि यस्तै सहायता कक्ष सञ्चालन गर्ने भनिएको छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'english.onlinekhabar.com',
            'url' => 'https://english.onlinekhabar.com/?p=594515',
          ),
        ),
      ),
    ),
    'tips' => 
    array (
      0 => 
      array (
        'en' => 'Carry your original ID plus a couple of photocopies. Indians should carry a passport or original voter ID; Nepalis should carry a passport or citizenship certificate. Aadhaar alone is not enough.',
        'ne' => 'सक्कल परिचयपत्र र त्यसका केही फोटोकपी साथमा राख्नुहोस्। भारतीयले राहदानी वा सक्कल मतदाता परिचयपत्र बोक्नुहोस्; नेपालीले राहदानी वा नागरिकता प्रमाणपत्र बोक्नुहोस्। आधार कार्ड मात्र पर्याप्त हुँदैन।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'indembkathmandu.gov.in',
            'url' => 'https://indembkathmandu.gov.in/consular-services-2',
          ),
          1 => 
          array (
            'label' => 'www.khaleejtimes.com',
            'url' => 'https://www.khaleejtimes.com/world/asia/nepal-seeks-india-approval-national-identity-card-cross-border-travel',
          ),
          2 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/lumbini-pradesh/2026/08/05/en/ration-card-or-banking-document-now-required-when-crossing-the-border-52-14.html',
          ),
        ),
      ),
      1 => 
      array (
        'en' => 'Travelling with children or elderly parents? If possible, carry a passport for each person. If not, bring a photo ID for every family member plus proof of the relationship, such as a ration card or school ID. These family rules date from 2019, so a passport is the safest choice.',
        'ne' => 'बालबालिका वा वृद्ध आमाबुबासँग यात्रा गर्दै हुनुहुन्छ? सम्भव भए हरेकको राहदानी बोक्नुहोस्। नभए परिवारका हरेक सदस्यको फोटो परिचयपत्र र नाताको प्रमाण, जस्तै राशन कार्ड वा विद्यालयको परिचयपत्र, साथमा राख्नुहोस्। परिवारसम्बन्धी यी नियम २०१९ का हुन्, त्यसैले राहदानी नै सबैभन्दा सुरक्षित उपाय हो।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'www.businesstoday.in',
            'url' => 'https://www.businesstoday.in/amp/latest/story/home-ministry-tweaks-travel-norms-indians-over-65-under-15-can-use-aadhaar-to-visit-nepal-bhutan-165900-2019-01-21',
          ),
          1 => 
          array (
            'label' => 'indembkathmandu.gov.in',
            'url' => 'https://indembkathmandu.gov.in/consular-services-2',
          ),
        ),
      ),
      2 => 
      array (
        'en' => 'Keep your bus ticket (PDF or image) on your phone, plus a printout. Border officials record where travellers are coming from and going to, and the ticket answers that quickly.',
        'ne' => 'बस टिकट (PDF वा फोटो) फोनमा र एउटा प्रिन्ट गरेर साथमा राख्नुहोस्। नाकामा यात्रु कहाँबाट आएको र कहाँ जाँदै छ भन्ने अभिलेख राखिन्छ, र टिकटले यसको छिटो जवाफ दिन्छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/news/2025/05/09/identity-card-mandatory-in-nepal-india-border-collection-of-records-at-the-border-47-27.html',
          ),
        ),
      ),
      3 => 
      array (
        'en' => 'Carry small notes in both INR and NPR. Indian notes of ₹100 and below are easiest. Bring ₹200/₹500 notes only from the new series and keep the total under ₹25,000 per person. Never carry old ₹500 or ₹1,000 notes. Exchange money only at banks or authorised money changers.',
        'ne' => 'भारतीय र नेपाली दुवै रुपैयाँका साना नोट साथमा राख्नुहोस्। रु. १०० र सोभन्दा साना भारतीय नोट सबैभन्दा सजिला हुन्छन्। रु. २००/५०० का नयाँ नोट मात्र ल्याउनुहोस् र प्रतिव्यक्ति जम्मा रु. २५,००० भन्दा कम राख्नुहोस्। पुराना रु. ५०० वा रु. १,००० का नोट कहिल्यै नबोक्नुहोस्। पैसा बैंक वा अनुमतिप्राप्त मनी एक्सचेन्जरमा मात्र सटही गर्नुहोस्।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'www.rbi.org.in',
            'url' => 'https://www.rbi.org.in/Scripts/NotificationUser.aspx?Id=13216',
          ),
          1 => 
          array (
            'label' => 'www.dtnext.in',
            'url' => 'https://www.dtnext.in/news/business/nepal-eases-post-demonetisation-curbs-on-indian-currency-allows-rs-200-rs-500-notes',
          ),
          2 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/business/2026/07/23/en/bankmoney-changer-facility-to-exchange-up-to-inr-25000-per-person-58-54.html',
          ),
        ),
      ),
      4 => 
      array (
        'en' => 'Before you travel, check the news for border closures. Banke\'s crossings were fully closed for 72 hours before Nepal\'s March 2026 election.',
        'ne' => 'यात्रा गर्नुअघि नाका बन्दको समाचार हेर्नुहोस्। नेपालको मार्च २०२६ को निर्वाचनअघि बाँकेका नाका ७२ घण्टा पूर्ण रूपमा बन्द भएका थिए।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'english.ratopati.com',
            'url' => 'https://english.ratopati.com/story/50541/house-of-representatives-election-all-border-crossings-in-banke-to-be-closed-for-72-hours',
          ),
        ),
      ),
      5 => 
      array (
        'en' => 'Foreign (non-Indian, non-Nepali) passengers: get your Indian visa before travelling (e-Visa holders can enter at Rupaidiha). Get your Nepal visa and entry stamp at the Jamunaha immigration office. Never cross without the proper stamps; illegal entry can mean jail.',
        'ne' => 'विदेशी (भारतीय र नेपालीबाहेक) यात्रु: यात्राअघि नै भारतीय भिसा लिनुहोस् (ई-भिसा भएकाले रुपैडिहाबाट प्रवेश गर्न सक्छन्)। नेपाल भिसा र प्रवेश छाप जमुनाहा अध्यागमन कार्यालयमा लिनुहोस्। आवश्यक छापबिना कहिल्यै सीमा पार नगर्नुहोस्; अवैध प्रवेशमा जेल पनि हुन सक्छ।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'xn--i1b5bzbybhfo5c8b4bxh.xn--11b7cb3a6a.xn--h2brj9c',
            'url' => 'https://xn--i1b5bzbybhfo5c8b4bxh.xn--11b7cb3a6a.xn--h2brj9c/sites/default/files/2026-01/List_of_ICPs_%28Immigration_Checkpost%29_20012026.pdf',
          ),
          1 => 
          array (
            'label' => 'ekantipur.com',
            'url' => 'https://ekantipur.com/lumbini-pradesh/2026/01/31/en/jamuna-border-crossing-opens-to-third-country-nationals-after-6-years-57-15.html',
          ),
          2 => 
          array (
            'label' => 'www.etvbharat.com',
            'url' => 'https://www.etvbharat.com/en/state/two-foreign-nationals-jailed-for-illegal-entry-at-indo-nepal-border-in-uttar-pradesh-enn26040801766',
          ),
        ),
      ),
      6 => 
      array (
        'en' => 'In the festival rush, watch your bags and cash and stay alert for fraud. If you need help, go to the official passenger help desk at Jamunaha or at the Nepalgunj and Kohalpur bus parks.',
        'ne' => 'चाडपर्वको भीडमा झोला र नगदमा ध्यान दिनुहोस् र ठगीबाट सतर्क रहनुहोस्। सहयोग चाहिए जमुनाहा वा नेपालगन्ज र कोहलपुर बसपार्कको आधिकारिक यात्रु सहायता कक्षमा जानुहोस्।',
        'hi' => '',
        'sources' => 
        array (
          0 => 
          array (
            'label' => 'english.onlinekhabar.com',
            'url' => 'https://english.onlinekhabar.com/?p=594515',
          ),
        ),
      ),
      7 => 
      array (
        'en' => 'Driving your own Indian vehicle into Nepal? Get the bhansar (customs) pass at the border or online, keep it with you, and remember the limit of 30 days in Nepal per calendar year.',
        'ne' => 'आफ्नै भारतीय सवारी लिएर नेपाल जाँदै हुनुहुन्छ? सीमामा वा अनलाइन भन्सार पास लिनुहोस्, साथमा राख्नुहोस्, र एक पात्रो वर्षमा नेपालमा बस्न पाउने सीमा ३० दिन हो भन्ने नबिर्सनुहोस्।',
        'hi' => '',
        'sources' => 
